#!/usr/bin/env node
/**
 * Accuracy + latency benchmark: OpenCV wechat_qrcode (this repo) vs zxing-wasm vs jsQR.
 *
 * All decoders get the exact same pixels: the raw RGBA corpus generated by
 * tools/gen_test_assets.py. The corpus has a deliberately hostile "hard" tier (far/small
 * codes, defocus, night shots, glare, extreme perspective) because a clean QR image is
 * not a useful accuracy benchmark for WeChat's detector + super-resolution pipeline.
 *
 * Usage:
 *   node tests/benchmark.mjs [--filter hard] [--tiles 2] [--json build/benchmark.json] [--md BENCHMARK.md]
 *
 * zxing-wasm and jsQR are devDependencies (npm install); the script degrades gracefully
 * when the baseline decoders are missing.
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';

import { assetsDir, filterAssets, loadManifest, loadWrapper, repoRoot, resultsMatchAsset, scanRgba } from './_harness.mjs';

const args = process.argv.slice(2);
const flag = (name, fallback = null) => {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : fallback;
};
const filter = flag('--filter');
const tiles = Number(flag('--tiles', '0'));
const jsonOut = flag('--json', join(repoRoot, 'build', 'benchmark.json'));
const mdOut = flag('--md');

/** @type {{name: string, label: string, decode: Function}[]} */
const decoders = [];

async function initWeChat() {
  const scanner = await loadWrapper();
  return {
    decode: (rgba, width, height) => {
      const result = scanRgba(scanner, rgba, width, height, { tiles });
      return { texts: result.results.map((r) => r.text), ms: result.ms };
    },
    destroy: () => scanner.destroy(),
  };
}

async function initZXing() {
  let mod;
  try {
    mod = await import('zxing-wasm/reader');
  } catch {
    console.warn('zxing-wasm not installed, skipping baseline');
    return null;
  }
  const wasmPath = join(repoRoot, 'node_modules', 'zxing-wasm', 'dist', 'reader', 'zxing_reader.wasm');
  let wasmBinary;
  try {
    wasmBinary = new Uint8Array(readFileSync(wasmPath));
  } catch {
    console.warn(`zxing-wasm wasm not found at ${wasmPath}, skipping baseline`);
    return null;
  }
  await mod.prepareZXingModule({ overrides: { wasmBinary }, fireImmediately: true });
  return {
    decode: async (rgba, width, height) => {
      const t0 = performance.now();
      const results = await mod.readBarcodes({ data: rgba, width, height }, {
        formats: ['QRCode'],
        tryHarder: true,
        tryRotate: true,
        tryInvert: true,
        tryDownscale: true,
      });
      return {
        texts: results.filter((r) => r.isValid !== false).map((r) => r.text),
        ms: performance.now() - t0,
      };
    },
  };
}

async function initJsQR() {
  let mod;
  try {
    mod = await import('jsqr');
  } catch {
    console.warn('jsqr not installed, skipping baseline');
    return null;
  }
  const jsQR = mod.default ?? mod;
  return {
    decode: (rgba, width, height) => {
      const t0 = performance.now();
      const result = jsQR(new Uint8ClampedArray(rgba), width, height, { inversionAttempts: 'attemptBoth' });
      return { texts: result ? [result.data] : [], ms: performance.now() - t0 };
    },
  };
}

async function main() {
  // Multi-code scenes are covered by tests/run-tests.mjs; the benchmark measures single-code
  // accuracy/latency so the comparison against jsQR (one code per call) stays apples-to-apples.
  const assets = filterAssets((await loadManifest()).assets, filter).filter((a) => !a.tags.includes('multi'));

  const wechat = await initWeChat();
  decoders.push({ name: 'wechat', label: 'OpenCV wechat_qrcode (this repo)', ...wechat });
  const zxing = await initZXing();
  if (zxing) decoders.push({ name: 'zxing-wasm', label: 'zxing-wasm', ...zxing });
  const jsqr = await initJsQR();
  if (jsqr) decoders.push({ name: 'jsqr', label: 'jsQR', ...jsqr });

  const corpus = [];
  for (const asset of assets) {
    corpus.push({ asset, rgba: new Uint8Array(await readFile(join(assetsDir, asset.raw))) });
  }

  const summary = [];
  for (const decoder of decoders) {
    const rows = [];
    for (const { asset, rgba } of corpus) {
      // warm-up on the first asset so wasm/JS JIT setup is not charged to the measurement
      if (rows.length === 0) await decoder.decode(rgba, asset.width, asset.height);
      const { texts, ms } = await decoder.decode(rgba, asset.width, asset.height);
      const ok = resultsMatchAsset(texts.map((text) => ({ text })), asset);
      rows.push({ id: asset.id, tags: asset.tags, ok, ms });
    }
    const decoded = rows.filter((r) => r.ok).length;
    const clean = rows.filter((r) => r.tags.includes('clean'));
    const hard = rows.filter((r) => r.tags.includes('hard'));
    summary.push({
      name: decoder.name,
      label: decoder.label,
      decoded,
      total: rows.length,
      cleanDecoded: clean.filter((r) => r.ok).length,
      cleanTotal: clean.length,
      hardDecoded: hard.filter((r) => r.ok).length,
      hardTotal: hard.length,
      avgMs: rows.reduce((sum, r) => sum + r.ms, 0) / rows.length,
      rows,
    });
  }

  // Console matrix: one row per asset, one column per decoder.
  const pad = (s, n) => String(s).padEnd(n);
  const padStart = (s, n) => String(s).padStart(n);
  const header = `${pad('asset', 26)} ${pad('tags', 20)} ${decoders.map((d) => padStart(d.name, 11)).join(' ')}`;
  console.log(`\n${header}`);
  console.log('-'.repeat(header.length));
  for (let i = 0; i < corpus.length; i++) {
    const cells = summary.map((s) => {
      const row = s.rows[i];
      return padStart(row.ok ? `✓ ${Math.round(row.ms)}ms` : '✗', 11);
    });
    console.log(`${pad(corpus[i].asset.id, 26)} ${pad(corpus[i].asset.tags.join(','), 20)} ${cells.join(' ')}`);
  }
  console.log('-'.repeat(header.length));
  for (const s of summary) {
    console.log(
      `${pad(s.label, 40)} decoded ${s.decoded}/${s.total}` +
        ` | clean ${s.cleanDecoded}/${s.cleanTotal}` +
        ` | hard ${s.hardDecoded}/${s.hardTotal}` +
        ` | avg ${s.avgMs.toFixed(1)}ms`,
    );
  }

  // Markdown report
  const md = [];
  md.push('# QR decode accuracy benchmark\n');
  md.push(`Generated by \`tests/benchmark.mjs\` from \`tests/assets/manifest.json\` (${corpus.length} assets).`);
  md.push(
    'The corpus is generated by `tools/gen_test_assets.py` and contains a clean reference set plus a',
    'deliberately hostile "hard" tier (far/small codes, defocus, night, glare, strong perspective, recompression).',
    'All decoders receive identical raw RGBA pixels; latency is measured in node on the same machine.',
    'Multi-code scenes are excluded here (jsQR decodes a single code per call); they are covered by tests/run-tests.mjs.\n',
  );
  md.push(`Decoder configuration: tiled fallback ${tiles > 1 ? `${tiles}x${tiles}` : 'disabled'} for wechat_qrcode.\n`);
  md.push('| decoder | decoded | clean set | hard tier | avg latency |');
  md.push('| --- | --- | --- | --- | --- |');
  for (const s of summary) {
    md.push(
      `| ${s.label} | ${s.decoded}/${s.total} (${((100 * s.decoded) / s.total).toFixed(0)}%) | ` +
        `${s.cleanDecoded}/${s.cleanTotal} | ${s.hardDecoded}/${s.hardTotal} | ${s.avgMs.toFixed(1)} ms |`,
    );
  }
  md.push('\n## Per-asset results\n');
  md.push(`| asset | tags | ${decoders.map((d) => d.name).join(' | ')} |`);
  md.push(`| --- | --- | ${decoders.map(() => '---').join(' | ')} |`);
  for (let i = 0; i < corpus.length; i++) {
    const cells = summary.map((s) => {
      const row = s.rows[i];
      return row.ok ? `✓ ${Math.round(row.ms)}` : '✗';
    });
    md.push(`| ${corpus[i].asset.id} | ${corpus[i].asset.tags.join(', ')} | ${cells.join(' | ')} |`);
  }
  md.push('\n`✓` = payload decoded, number = milliseconds. `✗` = payload not decoded.');
  md.push('');

  if (jsonOut) {
    writeFileSync(jsonOut, JSON.stringify({ generatedAt: new Date().toISOString(), tiles, summary }, null, 2));
    console.log(`\nwrote ${jsonOut}`);
  }
  if (mdOut) {
    writeFileSync(mdOut, md.join('\n'));
    console.log(`wrote ${mdOut}`);
  }

  wechat.destroy?.();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
